import {CORES,SUPPORTS,compileLoadoutTechnique,CREW} from './mako.js?v=5.16.0';
import {schoolFor} from './constellation-model.js';
const el=(t,c,text)=>{const n=document.createElement(t);if(c)n.className=c;if(text!==undefined)n.textContent=text;return n;};
export function equipRecipe(state,id,index,core,support){const h=state.heroes[id];if(state.mode==='battle'||!state.recruited.includes(id)||!h?.loadout?.[index]||!state.cores.includes(core)||!state.supports.includes(support))return false;const slot=h.loadout[index];if(slot.core!==core)delete slot.makoId;slot.core=core;slot.support=support;return true;}
export function loomTechnique(state,id,index,core,support){const hero=state.heroes[id],existing=hero.loadout?.[index];return compileLoadoutTechnique({core,support,...(existing?.core===core&&existing.makoId?{makoId:existing.makoId}:{})},hero,state);}
export function recipeLoom({world,onSave,onBack}){const s=world.state,root=el('section','recipe-loom');let hero=s.party[0],core=s.heroes[hero].loadout[0]?.core||'earth',support='focus',slot=0,filter='all';
 function paint(){root.replaceChildren();const h=s.heroes[hero];root.append(el('small','atlas-kicker','MAKO • THE RECIPE LOOM'),el('h3','','Weave a move, then make it yours'),el('p','atlas-fine','Read a core across its support patterns. Every recipe spends MP; geometry, timing and counters matter more than collecting a bigger number. Only discovered patterns can be equipped.'));
  const tools=el('div','atlas-toolbar'),crew=el('select');crew.setAttribute('aria-label','Recipe companion');for(const id of s.recruited)crew.add(new Option(CREW[id].name,id));crew.value=hero;crew.onchange=()=>{hero=Number(crew.value);slot=0;paint();};tools.append(crew);const targets=el('select');targets.setAttribute('aria-label','Recipe focus');for(const[v,t]of [['all','All recipes'],['heal','Healing & protection'],['attack','Attack recipes'],['team','Echo, Link & persistent fields']])targets.add(new Option(t,v));targets.value=filter;targets.onchange=()=>{filter=targets.value;paint();};tools.append(targets);root.append(tools);
  const grid=el('div','loom-grid'),table=el('table'),head=el('tr');head.append(el('th','','Core / support'));for(const sp of SUPPORTS)head.append(el('th','',sp.name));const thead=el('thead');thead.append(head);table.append(thead);const body=el('tbody');
  for(const c of CORES){if(filter==='heal'&&!c.healing||filter==='attack'&&c.healing)continue;const row=el('tr'),label=el('th','',c.name);label.style.color=c.color;row.append(label);for(const sp of SUPPORTS){const cell=el('td'),known=s.cores.includes(c.id)&&s.supports.includes(sp.id),tech=loomTechnique(s,hero,slot,c.id,sp.id),b=el('button',core===c.id&&support===sp.id?'selected':'',known?tech.cost+' MP':'◇');b.disabled=!known||filter==='team'&&!['link','echo','field'].includes(sp.id);b.setAttribute('aria-label',known?tech.name+' · '+tech.cost+' MP':'Undiscovered '+c.name+' / '+sp.name);b.onclick=()=>{core=c.id;support=sp.id;paint();};cell.append(b);row.append(cell);}body.append(row);}table.append(body);grid.append(table);root.append(grid);
  const known=s.cores.includes(core)&&s.supports.includes(support),tech=loomTechnique(s,hero,slot,core,support),detail=el('div','loom-details');detail.style.borderColor=tech.color;detail.append(el('h4','',tech.name),el('p','',`${tech.cost} MP · Rank ${tech.rank} · ${tech.shape} · Power coefficient ${tech.power.toFixed(2)}. This coefficient is not guaranteed damage: armor, status, partners and position change the result.`));
  const effects=[tech.interrupt?'Interrupts charged attacks':null,tech.echo?'One delayed repeat':null,tech.field?'Creates a three-tick field':null,tech.link?'Consumes partner MP and focus':null,tech.counter?'Waits for an incoming hit':null,tech.healing?'Restores or shields allies':null,tech.strainRebate?'Relieves '+tech.strainRebate+' strain after paying':null,tech.masteryBonus?'+'+tech.masteryBonus+' core AP on a paid cast':null].filter(Boolean);detail.append(el('p','',effects.join(' · ')||'Direct action. Keep an eye on the enemy warning and your remaining focus.'));
  const schools=(h.doctrineSlots||[]).map(schoolFor).filter(Boolean);detail.append(el('p','atlas-fine','Equipped schools: '+(schools.map(x=>x.name).join(' + ')||'none')+'. Conditional capstones resolve against the actual target.'));
  const chooser=el('select');chooser.setAttribute('aria-label','Destination Mako socket');for(let i=0;i<h.loadout.length;i++)chooser.add(new Option('Socket '+(i+1),i));chooser.value=slot;chooser.onchange=()=>{slot=Number(chooser.value);paint();};const equip=el('button','primary','Equip this recipe');equip.disabled=!known||!h.loadout.length||s.mode==='battle';equip.onclick=()=>{if(equipRecipe(s,hero,slot,core,support)){onSave();const receipt=el('p','node-state',tech.name+' equipped in socket '+(slot+1)+'.');detail.append(receipt);}};detail.append(chooser,equip);root.append(detail);const back=el('button','','Back to Crystal craft');back.onclick=onBack;root.append(back);
 }root.onkeydown=e=>{if(e.code==='Escape'){e.preventDefault();e.stopPropagation();onBack();}};paint();return root;}
